#[test]
fn test_a_number_alone_at_the_foot_of_every_page_is_a_page_number() {
    let wd: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ln: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let et: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let txt: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let md: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let lb: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let t1: &mut String = &mut crate::port::new_text();
    let t2: &mut String = &mut crate::port::new_text();
    let t3: &mut String = &mut crate::port::new_text();
    // Four pages, a bare number centred in the bottom margin: dropped from the flow, kept as the page's label.
    fl_pages(wd, ln, et, 4);
    fl_bottom(wd, ln, et, &crate::testport::text_blob("1")[..], 1, 30000, 31000);
    fl_bottom(wd, ln, et, &crate::testport::text_blob("2")[..], 2, 30000, 31000);
    fl_bottom(wd, ln, et, &crate::testport::text_blob("3")[..], 3, 30000, 31000);
    fl_bottom(wd, ln, et, &crate::testport::text_blob("4")[..], 4, 30000, 31000);
    crate::testport::assert_eq(fl_run(wd, ln, et, 4, 0, 0, txt, md, lb, t1), 0, "number: well formed");
    crate::testport::assert_text(t1, "L1=1;L2=2;L3=3;L4=4;Dp@1:1;Dp@2:2;Dp@3:3;Dp@4:4;P:alpha beta. |alpha beta. |alpha beta. |alpha beta.;", "page numbers: labels, ledger rows, and not a word of them in the body");
    // `keep`: nothing leaves the flow (the labels of /PageLabels would still come, but there are none).
    crate::testport::assert_eq(fl_run(wd, ln, et, 4, 0, 1, txt, md, lb, t2), 0, "keep: well formed");
    crate::testport::assert_text(t2, "P:alpha beta.;P:1;P:alpha beta.;P:2;P:alpha beta.;P:3;P:alpha beta.;P:4;", "keep: every line stays where it was");
    // `drop` takes the same here: a page number is dropped by the policy too.
    crate::testport::assert_eq(fl_run(wd, ln, et, 4, 0, 2, txt, md, lb, t3), 0, "drop: well formed");
    crate::testport::assert_text(t3, "L1=1;L2=2;L3=3;L4=4;Dp@1:1;Dp@2:2;Dp@3:3;Dp@4:4;P:alpha beta. |alpha beta. |alpha beta. |alpha beta.;", "drop: the same");
}
