#[test]
fn test_roman_numerals_and_arabic_are_two_runs_of_labels() {
    let wd: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ln: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let et: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let txt: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let md: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let lb: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let t1: &mut String = &mut crate::port::new_text();
    let t2: &mut String = &mut crate::port::new_text();
    // Front matter in roman numerals (centred), the body in arabic: the label is the number AS PRINTED.
    fl_pages(wd, ln, et, 6);
    fl_bottom(wd, ln, et, &crate::testport::text_blob("i")[..], 1, 30000, 31000);
    fl_bottom(wd, ln, et, &crate::testport::text_blob("ii")[..], 2, 30000, 31000);
    fl_bottom(wd, ln, et, &crate::testport::text_blob("iii")[..], 3, 30000, 31000);
    fl_bottom(wd, ln, et, &crate::testport::text_blob("1")[..], 4, 30000, 31000);
    fl_bottom(wd, ln, et, &crate::testport::text_blob("2")[..], 5, 30000, 31000);
    fl_bottom(wd, ln, et, &crate::testport::text_blob("3")[..], 6, 30000, 31000);
    crate::testport::assert_eq(fl_run(wd, ln, et, 6, 0, 0, txt, md, lb, t1), 0, "roman: well formed");
    crate::testport::assert_text(t1, "L1=i;L2=ii;L3=iii;L4=1;L5=2;L6=3;Dp@1:i;Dp@2:ii;Dp@3:iii;Dp@4:1;Dp@5:2;Dp@6:3;P:alpha beta. |alpha beta. |alpha beta. |alpha beta. |alpha beta. |alpha beta.;", "`i ii iii` then `1 2 3`");
    // A word that is a roman numeral is a word: `mix` at the foot of two pages is not a page number, and neither is a lone `I`.
    fl_clear(wd, ln, et);
    fl_pages(wd, ln, et, 3);
    fl_bottom(wd, ln, et, &crate::testport::text_blob("mix")[..], 1, 30000, 32000);
    fl_bottom(wd, ln, et, &crate::testport::text_blob("mix")[..], 2, 30000, 32000);
    fl_bottom(wd, ln, et, &crate::testport::text_blob("mix")[..], 3, 30000, 32000);
    crate::testport::assert_eq(fl_run(wd, ln, et, 3, 0, 0, txt, md, lb, t2), 0, "mix: well formed");
    crate::testport::assert_text(t2, "Ff1,2,3:mix;P:alpha beta. |alpha beta. |alpha beta.;", "a word at the foot of every page is furniture to keep, never a label");
}
