fn test_a_line_seen_on_one_page_is_not_furniture() {
    let wd: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ln: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let et: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let txt: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let md: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let lb: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let t1: &mut String = &mut crate::port::new_text();
    let t2: &mut String = &mut crate::port::new_text();
    // A single page has no recurrence to find: a line in the margin of a SIXTEEN-page document that is on one page only is
    // left in the flow.
    fl_pages(wd, ln, et, 16);
    fl_top(wd, ln, et, &crate::testport::text_blob("Draft for review")[..], 5, 7200, 30000);
    crate::testport::assert_eq(fl_run(wd, ln, et, 16, 0, 0, txt, md, lb, t1), 0, "once: well formed");
    // (A one-line page's line fills its fragment, so P4.1 continues the paragraph over the page break: `|`.)
    crate::testport::assert_text(t1, "P:alpha beta. |alpha beta. |alpha beta. |alpha beta.;P:Draft for review;P:alpha beta. |alpha beta. |alpha beta. |alpha beta. |alpha beta. |alpha beta. |alpha beta. |alpha beta. |alpha beta. |alpha beta. |alpha beta. |alpha beta.;", "a line on one page of sixteen stays in the flow");
    // On two pages of sixteen it is still not enough (30 per cent of the pages are needed).
    fl_clear(wd, ln, et);
    fl_pages(wd, ln, et, 16);
    fl_top(wd, ln, et, &crate::testport::text_blob("Draft for review")[..], 5, 7200, 30000);
    fl_top(wd, ln, et, &crate::testport::text_blob("Draft for review")[..], 9, 7200, 30000);
    crate::testport::assert_eq(fl_run(wd, ln, et, 16, 0, 0, txt, md, lb, t2), 0, "twice: well formed");
    crate::testport::assert_text(t2, "P:alpha beta. |alpha beta. |alpha beta. |alpha beta.;P:Draft for review;P:alpha beta. |alpha beta. |alpha beta. |alpha beta.;P:Draft for review;P:alpha beta. |alpha beta. |alpha beta. |alpha beta. |alpha beta. |alpha beta. |alpha beta. |alpha beta.;", "on two pages of sixteen it is still not enough");
}
