fn test_page_labels_of_the_catalogue_win_over_the_printed_numbers() {
    let wd: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ln: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let et: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let txt: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let md: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let lb: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let t1: &mut String = &mut crate::port::new_text();
    let mut i: i32 = 0;
    // Two pages numbered 5 and 6 at the foot, and a catalogue that says lower roman from page 0 (ii at page 2): the labels
    // are the catalogue's, the printed numbers are still taken out of the flow.
    fl_pages(wd, ln, et, 2);
    fl_bottom(wd, ln, et, &crate::testport::text_blob("5")[..], 1, 30000, 31000);
    fl_bottom(wd, ln, et, &crate::testport::text_blob("6")[..], 2, 30000, 31000);
    while i < 60 {
        crate::port::cells_push(md, 0);
        i += 1;
    }
    crate::port::cells_set(md, 54, 1);
    // one range: first page 0, style r (3), no prefix, number 1 on the first page, 1 + the pages after the last, no bits
    crate::port::cells_push(lb, 0);
    crate::port::cells_push(lb, 3);
    crate::port::cells_push(lb, -1);
    crate::port::cells_push(lb, 0);
    crate::port::cells_push(lb, 1);
    crate::port::cells_push(lb, 2);
    crate::port::cells_push(lb, 0);
    crate::port::cells_push(lb, 0);
    crate::testport::assert_eq(fl_run(wd, ln, et, 2, 0, 0, txt, md, lb, t1), 0, "labels: well formed");
    crate::testport::assert_text(t1, "L1=i;L2=ii;Dp@1:5;Dp@2:6;P:alpha beta. |alpha beta.;", "the catalogue's labels, the printed numbers dropped");
}
