    if r != 0 {
        return -1;
    }
    np = pd_pg_count(pg);
    px_index_build(pdf, ar, dc, a, b, st, pg, idx);
    r = pm_run(pdf, ar, dc, a, b, st, pg, idx, txt, w, seen, md, xm, ol, lb, nd, nt);
